class Solution {
    public List<String> fullJustify(String[] words, int maxWidth) {
        List<String> res = new ArrayList<>();
        List<String> line = new ArrayList<>();
        int length = 0;
        for (String word : words) {
            if (length + line.size() + word.length() > maxWidth) {
                int spaces = maxWidth - length;
                int slots = Math.max(1, line.size() - 1);
                for (int i = 0; i < spaces; i++) {
                    int idx = i % slots;
                    line.set(idx, line.get(idx) + " ");
                }
                StringBuilder sb = new StringBuilder();
                for (String w : line) sb.append(w);
                res.add(sb.toString());
                line.clear();
                length = 0;
            }
            line.add(word);
            length += word.length();
        }
        StringBuilder lastSb = new StringBuilder();
        for (int i = 0; i < line.size(); i++) {
            if (i > 0) lastSb.append(" ");
            lastSb.append(line.get(i));
        }
        while (lastSb.length() < maxWidth) lastSb.append(" ");
        res.add(lastSb.toString());
        return res;
    }
}

