var fullJustify = function(words, maxWidth) {
    const res = [];
    let line = [];
    let length = 0;
    for (const word of words) {
        if (length + line.length + word.length > maxWidth) {
            const spaces = maxWidth - length;
            const slots = Math.max(1, line.length - 1);
            for (let i = 0; i < spaces; i++) {
                line[i % slots] += ' ';
            }
            res.push(line.join(''));
            line = [];
            length = 0;
        }
        line.push(word);
        length += word.length;
    }
    const lastLine = line.join(' ');
    res.push(lastLine.padEnd(maxWidth, ' '));
    return res;
};
